from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    separated_groups = []  # Step 2: Initialize an empty list to store separated groups
    stack = []  # Initialize a stack to keep track of open parentheses indices

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)  # Push the index of open parenthesis to the stack
        elif char == ')':
            if stack:  # Check if stack is not empty
                start = stack.pop()  # Pop the index of the corresponding open parenthesis
                separated_groups.append(paren_string[start:i+1])  # Extract the group between open and closing parenthesis

    return separated_groups  # Step 8: Return the list of separated groups

